#!/usr/bin/env python3
"""Run the shared repository Python checks from any build or working directory."""
from pathlib import Path
import argparse
import os
import subprocess
import sys
import unittest


def main() -> int:
    # Shared checks must not scatter generated bytecode into source folders.
    sys.dont_write_bytecode = True
    os.environ['PYTHONDONTWRITEBYTECODE'] = '1'
    # Repository text is UTF-8. Match CTest even when launched from a legacy
    # Windows console whose default encoding is a system code page.
    if os.name == 'nt' and not sys.flags.utf8_mode:
        return subprocess.call([sys.executable, '-X', 'utf8', __file__, *sys.argv[1:]])
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--list', action='store_true', help='list tests without running them')
    args = parser.parse_args()
    root = Path(__file__).resolve().parents[1]
    # Source-contract suites share the bounded implementation reader, including
    # when CTest launches this entry point from a configure/build directory.
    if str(root) not in sys.path:
        sys.path.insert(0, str(root))
    tests = root / 'Tests'
    suite = unittest.TestSuite()
    modules = {}
    for directory in sorted({p.parent for p in tests.rglob('test_*.py')
                             if '__pycache__' not in p.parts}):
        for path in directory.glob('test_*.py'):
            if path.stem in modules:
                parser.error(f'duplicate test module: {path} and {modules[path.stem]}')
            modules[path.stem] = path
        # Each suite is independently importable; test data need no __init__.py.
        loader = unittest.TestLoader()
        suite.addTests(loader.discover(str(directory), pattern='test_*.py'))
    if args.list:
        def entries(group):
            for test in group:
                if isinstance(test, unittest.TestSuite):
                    yield from entries(test)
                else:
                    yield test.id()
        print('\n'.join(entries(suite)))
        return 0
    return 0 if unittest.TextTestRunner(verbosity=1).run(suite).wasSuccessful() else 1


if __name__ == '__main__':
    sys.exit(main())
